package com.concertstage.stage;
import net.minecraft.core.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.util.RandomSource;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;import net.minecraft.world.phys.shapes.*;
/** Hidden, unticked spatial cells for connected equipment. */
public final class StageMountBlock extends Block implements EntityBlock{
 public StageMountBlock(Properties p){super(p);}public BlockEntity newBlockEntity(BlockPos p,BlockState s){return new StageAttachmentBlockEntity(p,s);}public RenderShape getRenderShape(BlockState s){return RenderShape.INVISIBLE;}
 public VoxelShape getShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){return l.getBlockEntity(p)instanceof StageAttachmentBlockEntity be?be.shape():Shapes.empty();}public VoxelShape getCollisionShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){return getShape(s,l,p,c);}public VoxelShape getBlockSupportShape(BlockState s,BlockGetter l,BlockPos p){return getShape(s,l,p,CollisionContext.empty());}
 public void onRemove(BlockState s,Level l,BlockPos p,BlockState n,boolean moving){if(!s.is(n.getBlock())&&!l.isClientSide&&!StageStructure.editing())StageModules.removedCell(l,p,true);super.onRemove(s,l,p,n,moving);}public void playerWillDestroy(Level l,BlockPos p,BlockState s,Player player){com.concertstage.block.Drops.breaking(l,player);if(!l.isClientSide&&player.getAbilities().instabuild)StageModules.removedCell(l,p,false);super.playerWillDestroy(l,p,s,player);}
 public InteractionResult use(BlockState s,Level l,BlockPos p,Player player,InteractionHand hand,BlockHitResult hit){return player.isShiftKeyDown()&&player.getItemInHand(hand).isEmpty()?StageModules.dismantle(l,p,player,hit):InteractionResult.PASS;}
 public BlockState updateShape(BlockState s,Direction d,BlockState n,LevelAccessor l,BlockPos p,BlockPos np){if(!l.isClientSide())l.scheduleTick(p,this,1);return s;}public void tick(BlockState s,ServerLevel l,BlockPos p,RandomSource random){StageModules.validate(l,p);}
 public net.minecraft.world.item.ItemStack getCloneItemStack(BlockGetter l,BlockPos p,BlockState s){if(l.getBlockEntity(p)instanceof StageAttachmentBlockEntity be)for(var e:be.entries())for(String key:StagePose.refunds(e.refund()).keySet()){var item=com.concertstage.StageContent.ITEMS.get(key);if(item!=null)return new net.minecraft.world.item.ItemStack(item);}return net.minecraft.world.item.ItemStack.EMPTY;}
}
